def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items, depending on whether that version is
        supported. If no protocol version is provided, all available versions will be returned.

            :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
            :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
            :raise TypeError: if protocol version is not passed in a tuple"""

    # check if a specific protocol version was provided
    if protocol_version is not None:
        # make sure it's a tuple
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol version must be passed in a tuple")

        # return a dictionary with just the specified version
        return {protocol_version: cls._version_to_handler_mapping(protocol_version)}

    # return a dictionary with all available versions
    return {version: cls._version_to_handler_mapping(version) for version in cls.supported_versions()}

