def discard(self, n=-1, qid=-1, dehydration_hooks=None,
            hydration_hooks=None, **handlers):
    if n == -1:
        n = len(self._output_queue)
    else:
        n = max(0, n)
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}
    if qid == -1:
        qid = len(self._query_ids) - 1
        if qid < 0:
            raise ValueError("There are no previous queries to discard.")
    for i in range(n):
        self._output_queue.append(("DISCARD", qid, dehydration_hooks, hydration_hooks))
    for handler in handlers.values():
        self.Register(handler)
    return Response(self, self._qid)
