def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None, db=None, imp_user=None, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    try:
        if not isinstance(mode, (str, None)):
            raise TypeError("The 'mode' parameter must be a string or None.")
        if mode is not None and mode not in ("READ", "WRITE"):
            raise ValueError(f"Invalid value for 'mode' parameter: {mode}")
        if not isinstance(bookmarks, (list, tuple, None)):
            raise TypeError("The 'bookmarks' parameter must be an iterable of bookmark values, or None.")
        if not isinstance(metadata, (dict, None)):
            raise TypeError("The 'metadata' parameter must be a dictionary of custom metadata, or None.")
        if not isinstance(timeout, (int, float, None)):
            raise TypeError("The 'timeout' parameter must be a positive number, or None.")
        if timeout is not None and timeout < 0:
            raise ValueError(f"The timeout parameter must be a positive number, got {timeout}")
        if not isinstance(db, (str, None)):
            raise TypeError("The 'db' parameter must be a string, or None.")
        if not isinstance(imp_user, (str, None)):
            raise TypeError("The 'imp_user' parameter must be a string, or None.")
        if not isinstance(dehydration_hooks, (dict, None)):
            raise TypeError("The 'dehydration_hooks' parameter must be an dict of dehydration functions, or None.")
        if not isinstance(hydration_hooks, (dict, None)):
            raise TypeError("The 'hydration_hooks' parameter must be an dict of hydration functions, or None.")
        if not isinstance(handlers, (list, tuple, None)):
            raise TypeError("The handlers parameter must be a iterable of handler functions, or None.")

        request = self._create_begin_request(mode, bookmarks, metadata, timeout, db, imp_user, dehydration_hooks, hydration_hooks)
        response = self._send_request(request)
        return Response(self, handler=handlers)
    except (ValueError, TypeError) as e:
        print("Error:", e)
        return Response(self, handler=handlers)

def _create_begin_request(self, mode, bookmarks, metadata, timeout, db, imp_user, dehydration_hooks, hydration_hooks):
    request = {
        "tag": "Begin",
        "props": {
            "mode": mode,
            "bookmarks": bookmarks,
            "metadata": metadata,
            "timeout": timeout,
            "db": db,
            "imp_user": imp_user,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks,
        }
    }
    return request

def _send_request(self, request):
    response = requests.post(f"{self.url}/{self.project_name}/transactions", json=request)
    response.raise_for_status()
    return response.json()

def __handle_response(self, response):
    status_code = response["status"]
    method = status_code[0]
    if method == "s":
        return {"success": True}
    elif method == "f":
        return {"success": False, "code": response["metadata"]["code"], "message": response["metadata"]["message"]}
    else:
        raise RuntimeError(f"Unexpected result code: {response['metadata']['code']}")

