def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Check if classes is a list
    if not isinstance(classes, list):
        raise TypeError("Parameter 'classes' must be a list")

    # Check if all elements in classes are type Class
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError("All elements in 'classes' must be types")

    # Sort the classes by their hierarchy level in ascending order
    sorted_classes = sorted(classes, key=lambda cls: cls.mro())

    # Find the first class that is not a subclass of any other class in the list
    for i, cls in enumerate(sorted_classes):
        if all(not issubclass(other_cls, cls) for other_cls in sorted_classes[i+1:]):
            return cls

    # If no such class is found, return the last class in the list
    return sorted_classes[-1]

