    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that prior is an InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The prior variable must be an InventoryValidator object.")

    # Check that self and prior have the same inventory ID
    if self.inventory_id != prior.inventory_id:
        return False

    # Check that prior has a version number that is one less than self
    if prior.version_number != self.version_number - 1:
        return False

    # Check that all the items in prior are also in self
    for item in prior.items:
        if item not in self.items:
