def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extract number and supplement from an issue element.
    Input: <issue>xxxx</issue>
    Output: (number, supplement)
    """
    number, supplement = None, None
    issue = issue.strip()
    if issue:
        match = re.search(r'^(\d+)(?:[\s\-]?(spe|suppl|suppl\.|supl\.|suppl)(\.|\s|)(\d+))?$', issue, re.I)
        if match:
            number = int(match.group(1))
            supplement = match.group(4)
            if supplement:
                supplement = supplement.strip()
                if supplement.isdigit():
                    supplement = int(supplement)
    if not number:
        raise ValueError(f"Invalid number: '{issue}'")
    return number, supplement

