                raise RuntimeError(f"Command {command} failed with exit code {result.returncode}")
            if verbose:
                print(f"Command {command} completed successfully")
        return result.stdout.decode("utf-8")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command {command} failed with exit code {e.returncode}") from e
    except Exception as e:
        raise RuntimeError(f"Error occurred while running command {command}") from e

