def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    try:
        # Check if version_dirs is empty
        if not version_dirs:
            raise ValueError("version_dirs cannot be empty")

        # Check if version_dirs is sorted in increasing order
        if not all(version_dirs[i] < version_dirs[i+1] for i in range(len(version_dirs)-1)):
            raise ValueError("version_dirs must be sorted in increasing order")

        # Check if each version directory has an inventory file
        for version_dir in version_dirs:
            inventory_file = os.path.join(version_dir, "inventory.txt")
            if not os.path.exists(inventory_file):
                raise FileNotFoundError(f"Missing inventory file for version {version_dir}")

        # Check if the inventory files are consistent with the root inventory
        root_inventory = self.get_inventory()
        for version_dir in version_dirs:
            inventory_file = os.path.join(version_dir, "inventory.txt")
            with open(inventory_file, "r") as f:
                version_inventory = json.load(f)
            for content_digest in version_inventory:
                if content_digest not in root_inventory:
                    raise ValueError(f"Content digest '{content_digest}' in version {version_dir} not found in root inventory")
                if root_inventory[content_digest] != version_inventory[content_digest]:
                    raise ValueError(f"Content digest '{content_digest}' in version {version_dir} mismatch with root inventory")

