def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged_nodes = []
    for node in nodes:
        if not isinstance(node, tuple) or len(node) != 2:
            raise ValueError("Invalid node value: must be a tuple of length 2")
        key, value = node
        if not isinstance(key, ruamel.yaml.nodes.ScalarNode):
            raise ValueError("Invalid key value: must be a ScalarNode")
        if not isinstance(value, ruamel.yaml.nodes.Node):
            raise ValueError("Invalid value: must be a Node")
        if key.value in [node[0].value for node in merged_nodes]:
            # If the key already exists, merge the values
            existing_node = next(node for node in merged_nodes if node[0].value == key.value)
            existing_node[1].value = _deep_merge_values(existing_node[1], value)
        else:
            # Otherwise, add the new node
            merged_nodes.append(node)
    return merged_nodes

def _deep_merge_values(node1, node2):
    if not isinstance(node1, ruamel.yaml.nodes.MappingNode):
        raise ValueError("Invalid node type for deep merge: must be a MappingNode")
    if not isinstance(node2, ruamel.yaml.nodes.MappingNode):
        raise ValueError("Invalid node type for deep merge: must be a MappingNode")
    merged_values = {}
    for key, value in node1.value:
        if key in node2.value:
            # If the key exists in both nodes, deep merge the values
            merged_values[key] = _deep_merge_values(value, node2.value[key])
        else:
            # Otherwise, use the value from the first node
            merged_values[key] = value
    for key, value in node2.value:
        if key not in node1.value:
            # If the key is new to the first node, add it
            merged_values[key] = value
    return ruamel.yaml.nodes.MappingNode(
        tag='tag:yaml.org,2002:map', value=list(merged_values.items())
    )
