def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsers = {name: parser.parse_known_args for name, parser in subparsers.items()}
    parsed_args = {}
    remaining_args = []
    for parser in parsers.values():
        parsed_args, remaining_args = parser(unparsed_arguments)
        if not parsed_args:
            continue
        for name, namespace in parsed_args.items():
            if name not in subparsers:
                raise ValueError(f"Invalid subparser name: {name}")
        break
    return parsed_args, remaining_args

def paging(response, max_results):
    if not isinstance(response, list):
        raise TypeError("Response must be a list of objects")
    if not isinstance(max_results, int) or max_results < 1:
        raise ValueError("Max results must be a positive integer")

    total_count = len(response)
    page_count = (total_count + max_results - 1) // max_results

    for page_number in range(1, page_count + 1):
        start_index = (page_number - 1) * max_results
        end_index = min(page_number * max_results, total_count)
        yield response[start_index:end_index]

