def vertex3tuple(vertices):
    """Returns 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex."""
    if not vertices:
        return []
    if len(vertices) < 3:
        raise ValueError("Vertices must be a non-empty list of at least 3 points.")
    result = []
    for i in range(len(vertices)):
        j = (i + 1) % len(vertices)
        k = (i + 2) % len(vertices)
        result.append((vertices[i], vertices[j], vertices[k]))
    return result

