    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of strings")
    if not all(isinstance(c, str) for c in alphabet):
        raise TypeError("alphabet must contain only strings")
    if not (padding is None or isinstance(padding, int)):
        raise TypeError("padding must be an integer or None")

    base = len(alphabet)
    result = ""
    is_negative = number < 0
    if is_negative:
        number = -number

    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if is_negative:
        result = "-" + result

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("'number' must be an integer")

    if not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise TypeError("'alphabet' must be a list of strings")

    if padding is not None and not isinstance(padding, int):
        raise TypeError("'padding' must be an integer")

    if padding is not None and padding < 0:
        raise ValueError("'padding' must be a non-negative integer")

    if len(alphabet) < 2:
        raise ValueError("'alphabet' must have at least 2 elements")

    # Convert the number to a string using the given alphabet
    output = ""
    while number > 0:
        output = alphabet[number % len(alphabet)] + output
        number //= len(alphabet)

    # Pad the output if needed
    if padding is not None and len(output) < padding:
        output = (padding - len(output)) * alphabet[0] + output

    return output

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Convert the number to a list of base-10 digits
    digits = []
    while number > 0:
        digits.append(number % 10)
        number //= 10
    digits.reverse()

    # Convert each digit to a character in the alphabet
    for i in range(len(digits)):
        digits[i] = alphabet[digits[i]]

    # Optionally pad the output with spaces
    if padding is not None:
        while len(digits) < padding:
            digits.append(" ")

    # Return the final string
    return "".join(digits)

