    if padding is not None:
        if not isinstance(padding, int):
            raise ValueError("padding must be an integer")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    result = ""
    for char in range(len(alphabet), 0, -1):
        result += alphabet[char - 1] * (number // (10**char))
        number %= 10**char

    if padding is not None and padding > len(result):
        result = "0" * (padding - len(result)) + result

    return result

