def parse_frequency(frequency: str) -> Optional[datetime.timedelta]:
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None

    frequency_parts = frequency.split()
    if len(frequency_parts) != 2:
        raise ValueError(f"Invalid frequency: '{frequency}'")

    try:
        frequency_num = int(frequency_parts[0])
    except ValueError:
        raise ValueError(f"Invalid frequency: '{frequency}'")

    frequency_unit = frequency_parts[1].lower()
    if frequency_unit not in ["hour", "hours", "day", "days", "week", "weeks"]:
        raise ValueError(f"Invalid frequency: '{frequency}'")

    if frequency_unit == "hours":
        return datetime.timedelta(hours=frequency_num)
    elif frequency_unit == "days":
        return datetime.timedelta(days=frequency_num)
    elif frequency_unit == "weeks":
        return datetime.timedelta(weeks=frequency_num)
    else:
        raise ValueError(f"Invalid frequency: '{frequency}'")

