def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if type(commands) is not list:
            commands = [commands]
        for command in commands:
            if type(command) is str:
                command = [command]
            if cwd:
                p = subprocess.Popen(command, cwd=cwd, env=env)
            else:
                p = subprocess.Popen(command, env=env)
            if verbose:
                print("Running command:", command)
            stdout, stderr = p.communicate()
            if verbose:
                print("Command exited with status:", p.returncode)
            if hide_stderr:
                stderr = ""
            return stdout, stderr
    except Exception as e:
        return "", str(e)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A list of commands to run.
    :param args: A list of arguments to pass to each command.
    :param cwd: The directory to run the command in.
    :param verbose: Whether to print stdout and stderr.
    :param hide_stderr: Whether to hide stderr.
    :param env: The environment to run the command in.
    :return: The return code of the command.
    """
    if not commands:
        raise ValueError("No commands provided.")

    if not args:
        raise ValueError("No arguments provided.")

    if not cwd:
        cwd = os.getcwd()

    if not env:
        env = {}

    for command in commands:
        if not command:
            raise ValueError("Empty command.")

        if not args:
            raise ValueError("No arguments provided for command.")

        process = subprocess.Popen(command, cwd=cwd, env=env)
        stdout, stderr = process.communicate()

        if stdout and verbose:
            print(stdout)

        if stderr and not hide_stderr:
            print(stderr)

    return process.returncode

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: The command(s) to execute.
    :param args: A list of arguments to pass to the command(s).
    :param cwd: The current working directory.
    :param verbose: Whether to print the command output.
    :param hide_stderr: Whether to hide stderr output.
    :param env: The environment to use for the command execution.
    :return: The exit code of the last command executed, or None if there was an error.
    """
    try:
        if env is None:
            env = os.environ.copy()
        if isinstance(commands, str):
            commands = [commands]
        for command in commands:
            if verbose:
                print(f"Running command: {command}")
            result = subprocess.run(command, args, cwd=cwd, env=env, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT, universal_newlines=True)
            if result.returncode != 0:
                if verbose:
                    print(f"Command {command} failed with exit code {result.returncode}")
                return result.returncode
        return None
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Error running command: {e.cmd} {e.stdout}")
        return e.returncode

