def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers, keyed by version tuple.

    If an explicit protocol version is provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be passed in a tuple")

    # Return all supported protocol versions if no version is specified
    if protocol_version is None:
        return {
            (3, 1): Version3_1Handler,
            (3, 2): Version3_2Handler,
            (4, 0): Version4_0Handler,
            (4, 1): Version4_1Handler,
            (4, 2): Version4_2Handler,
        }

    # Return only the specified version if a version is specified
    if (3, 1) <= protocol_version < (3, 3):
        return {
            (3, 1): Version3_1Handler,
        }
    elif (3, 2) <= protocol_version < (3, 3):
        return {
            (3, 2): Version3_2Handler,
        }
    elif (4, 0) <= protocol_version < (4, 1):
        return {
            (4, 0): Version4_0Handler,
        }
    elif (4, 1) <= protocol_version < (4, 2):
        return {
            (4, 1): Version4_1Handler,
        }
    elif (4, 2) <= protocol_version < (4, 3):
        return {
            (4, 2): Version4_2Handler,
        }
    else:
        raise ValueError(f"Unsupported protocol version: {protocol_version}")

