    if tentative and not iface.providedBy(candidate):
        return False
    elif not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("Candidate does not provide interface")

    methods = set(iface.namesAndDescriptions())
    candidate_functions = set(dir(candidate))

    for method in methods:
        if not method in candidate_functions:
            raise zope.interface.Invalid(f"Candidate is missing method {method}")

        candidate_function = getattr(candidate, method)
        iface_function = getattr(iface, method)

        if not aspec(candidate_function) == aspec(iface_function):
            raise zope.interface.Invalid(f"Candidate method {method} has incorrect signature")

    attributes = set(iface.namesAndDescriptions(lambda name: isinstance(getattr(iface, name), Property)))
    candidate_attributes = set(dir(candidate))

    for attribute in attributes:
        if not attribute in candidate_attributes:
            raise zope.interface.Invalid(f"Candidate is missing attribute {attribute}")

        candidate_attribute = getattr(candidate, attribute)
        iface_attribute = getattr(iface, attribute)

        if not candidate_attribute == iface_attribute:
            raise zope.interface.Invalid(f"Candidate attribute {attribute} has incorrect value")

    return True

