def create_complex_argument_type(self, subcommand: str, type_name: str, option_name: str, spec_option: list) -> ColumnDefault:
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate input arguments
    if not isinstance(subcommand, str) or not subcommand.strip():
        raise ValueError("Invalid 'subcommand' argument: must be a non-empty string")
    if not isinstance(type_name, str) or not type_name.strip():
        raise ValueError("Invalid 'type_name' argument: must be a non-empty string")
    if not isinstance(option_name, str) or not option_name.strip():
        raise ValueError("Invalid 'option_name' argument: must be a non-empty string")
    if not isinstance(spec_option, list) or not spec_option:
        raise ValueError("Invalid 'spec_option' argument: must be a non-empty list")

    # Create the complex argument type
    argument_type = ColumnDefault(subcommand, type_name, option_name)

    # Add the specifications
    for spec in spec_option:
        try:
            argument_type.add_specification(spec)
        except ValueError as e:
            raise ValueError(f"Invalid specification '{spec}': {e}")

    return argument_type

