def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    try:
        # Validate input parameters
        if not isinstance(vars_dict, dict):
            raise ValueError("vars_dict must be a dictionary")
        if not isinstance(cli_args, list):
            raise ValueError("cli_args must be a list")
        if not isinstance(ir_workspace, AnsibleWorkspace):
            raise ValueError("ir_workspace must be an AnsibleWorkspace object")
        if not isinstance(ir_plugin, AnsiblePlugin):
            raise ValueError("ir_plugin must be an AnsiblePlugin object")

        # Build the command line arguments for ansible-playbook
        cmd_args = cli_args + ["-e", json.dumps(vars_dict)] + ["--"] + ["ir.yml"]

        # Run the ansible-playbook command using the infrared workspace's runner
        ir_runner = ir_workspace.runner
        results = ir_runner.run(cmd_args, stderr=subprocess.PIPE)

        # Raise an exception if the ansible-playbook command failed
        if results.returncode != 0:
            raise RuntimeError("Ansible playbook failed with exit code %d" % results.returncode)

        return results.stdout.decode("utf-8")
    except Exception as e:
        raise RuntimeError("Error running ansible-playbook: " + str(e)) from e

